"""Generates the standalone acceptance-test runner the FOUNDER'S agent
executes in the founder's own environment (scoping doc Decision 3b).

We never run their code on our infra at demo stage: no sandbox security
project, but real executable verification. The runner is dependency-free
stdlib Python so any agent can execute it anywhere; it emits results.json
which verification-loop scores.
"""
from __future__ import annotations

import json

from vmodel_contracts import AcceptanceTest

RUNNER_TEMPLATE = '''#!/usr/bin/env python3
"""Acceptance runner generated by verification-loop. Run in YOUR environment:
    python acceptance_runner.py --base-url http://localhost:3000
Emits results.json next to itself. Stdlib only, no installs."""
import argparse, json, sys, urllib.request, urllib.error

TESTS = {tests_json}

def run_http(t, base):
    d = t["definition"]
    req = urllib.request.Request(base + d["url"], method=d.get("method", "GET"),
                                 data=(json.dumps(d["body"]).encode() if d.get("body") else None),
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=10) as r:
            status = r.getcode()
    except urllib.error.HTTPError as e:
        status = e.code
    except Exception as e:
        return {"test_id": t["test_id"], "passed": False, "evidence": f"unreachable: {e}"}
    return {"test_id": t["test_id"], "passed": status == d.get("expect", 200),
             "evidence": f"{d.get('method','GET')} {d['url']} -> {status} (expected {d.get('expect',200)})"}

def run_cli(t, base):
    import subprocess
    d = t["definition"]
    try:
        p = subprocess.run(d["command"], shell=True, capture_output=True, text=True, timeout=60)
        ok = (p.returncode == d.get("expect_exit", 0)) and (d.get("expect_stdout", "") in p.stdout)
        return {"test_id": t["test_id"], "passed": ok, "evidence": p.stdout[-500:] or p.stderr[-500:]}
    except Exception as e:
        return {"test_id": t["test_id"], "passed": False, "evidence": str(e)}

def main():
    from . import model_config as _mc
    print(f"Models: {_mc.describe_models()}")
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", default="http://localhost:3000")
    args = ap.parse_args()
    results = []
    for t in TESTS:
        runner = {"http": run_http, "cli": run_cli}.get(t["runner"])
        if runner is None:
            results.append({"test_id": t["test_id"], "passed": None,
                             "evidence": f"runner '{t['runner']}' needs human/agent judgment"})
        else:
            results.append(runner(t, args.base_url))
    with open("results.json", "w") as f:
        json.dump(results, f, indent=2)
    print(f"{sum(1 for r in results if r['passed'])}/{len(results)} passed -> results.json")

if __name__ == "__main__":
    main()
'''


def generate_runner(tests: list[AcceptanceTest]) -> str:
    serializable = [
        {"test_id": t.test_id, "runner": t.runner, "definition": t.definition,
         "description": t.description}
        for t in tests if t.runner in ("http", "cli", "dom", "semantic")
    ]
    return RUNNER_TEMPLATE.replace("{tests_json}", json.dumps(serializable, indent=2))

